const lancamentos = $('Ler Lançamentos do Mês').all().map(i => i.json);
const orcamentos  = $('Ler Orçamentos').all().map(i => i.json);
const mes         = $('Webhook – Receber Mês').first().json.body?.mes || '';

// Montar mapa de limites: { 'Alimentação': 800, ... }
const limites = {};
orcamentos.forEach(o => {
  const cat    = o['Categoria']     || o['categoria']     || '';
  const limite = parseFloat(o['Limite Mensal (R$)'] || o['limite_mensal'] || 0);
  if (cat && limite > 0) limites[cat] = limite;
});

// Somar gastos por categoria (só Despesas)
const gastos = {};
lancamentos.forEach(l => {
  if ((l['Tipo']||l['tipo']||'') === 'Despesa') {
    const cat = l['Categoria']||l['categoria']||'Outros';
    const val = parseFloat(l['Valor (R$)']||l['valor']||0);
    gastos[cat] = (gastos[cat]||0) + val;
  }
});

// Detectar categorias ultrapassadas ou próximas do limite (>= 80%)
const alertas_100 = [];
const alertas_80  = [];

Object.entries(gastos).forEach(([cat, gasto]) => {
  const limite = limites[cat];
  if (!limite) return;
  const pct = gasto / limite;
  if (pct >= 1.0) {
    alertas_100.push({ cat, gasto, limite, pct });
  } else if (pct >= 0.8) {
    alertas_80.push({ cat, gasto, limite, pct });
  }
});

if (alertas_100.length === 0 && alertas_80.length === 0) {
  return [{ json: { enviar: false, mes } }];
}

// Montar mensagem WhatsApp
let msg = `⚠️ *Alerta de Orçamento – ${mes}*\n\n`;

if (alertas_100.length > 0) {
  msg += `🔴 *LIMITE ULTRAPASSADO:*\n`;
  alertas_100.forEach(a => {
    msg += `  • ${a.cat}: R$ ${a.gasto.toFixed(2).replace('.',',')} / R$ ${a.limite.toFixed(2).replace('.',',')} (${(a.pct*100).toFixed(0)}%)\n`;
  });
  msg += '\n';
}

if (alertas_80.length > 0) {
  msg += `🟡 *ATENÇÃO – próximo do limite:*\n`;
  alertas_80.forEach(a => {
    const restante = a.limite - a.gasto;
    msg += `  • ${a.cat}: R$ ${a.gasto.toFixed(2).replace('.',',')} / R$ ${a.limite.toFixed(2).replace('.',',')} (${(a.pct*100).toFixed(0)}%) – faltam R$ ${restante.toFixed(2).replace('.',',')}\n`;
  });
}

msg += `\n_Acesse o Google Sheets para ver o detalhamento._`;

return [{ json: { enviar: true, mes, mensagem: msg, alertas_100, alertas_80 } }];
